    def to_python(self, value):
        value = super().to_python(value)
        if value:
            # Detect scheme via partition to avoid calling urlsplit() on
            # potentially large or slow-to-normalize inputs.
            scheme, sep, _ = value.partition(":")
            if (
                not sep
                or not scheme
